#Requires -Version 5.1
[CmdletBinding()]
param(
    [Parameter(Mandatory)][string]$ApprovedSignerSid,
    [Parameter(Mandatory)][string]$ApprovedStart,
    [Parameter(Mandatory)][string]$ApprovedEnd
)
$ErrorActionPreference = 'Stop'
Set-StrictMode -Version Latest

# Run only via the independently verified, same-byte launcher in the handoff.
$expectedHost = Join-Path ([Environment]::GetFolderPath('Windows')) 'System32\WindowsPowerShell\v1.0\powershell.exe'
if (-not [Environment]::Is64BitProcess -or (Get-Process -Id $PID).Path -ine $expectedHost) {
    throw 'HOLD_UNAPPROVED_HOST'
}
$format = "yyyy-MM-dd'T'HH:mm:sszzz"
$culture = [Globalization.CultureInfo]::InvariantCulture
$start = [DateTimeOffset]::ParseExact($ApprovedStart, $format, $culture)
$end = [DateTimeOffset]::ParseExact($ApprovedEnd, $format, $culture)
$sid = [Security.Principal.SecurityIdentifier]::new($ApprovedSignerSid)
if ($sid.Value -cne $ApprovedSignerSid -or $start -ge $end) { throw 'HOLD_APPROVAL_INPUT' }

# The embedded assembly is compiled in advance from VerifierStorePreparation.cs.
$embeddedAssembly = ''
$type = [Reflection.Assembly]::Load([Convert]::FromBase64String($embeddedAssembly)).GetType('LimitlessVerifierStorePreparation', $true)
try {
    $record = $type::CreateOnce($sid.Value, $start, $end)
    "LEDGER_CREATED_HANDLE_VERIFIED=$record"
} catch {
    $cause = $_.Exception.GetBaseException()
    if ($cause -is [ComponentModel.Win32Exception]) {
        throw ("HOLD_NATIVE_ERROR_NO_RETRY_{0}" -f $cause.NativeErrorCode)
    }
    if ($cause.Message -match '^HOLD_[A-Z_]+$') { throw $cause.Message }
    throw 'HOLD_FAILED_NO_RETRY'
}
